    int ng = (int)blockIdx.x;
    int n = ng / G;
    int g = ng - n * G;
    int Cg = C / G;
    int HW = H * W;
    int64_t group_base = ((int64_t)n * C + (int64_t)g * Cg) * (int64_t)HW;

    float sum = 0.0f;
    float sumsq = 0.0f;

    int elements = Cg * HW;
    for (int i = (int)threadIdx.x; i < elements; i += (int)blockDim.x) {
