    sh_sumsq[tid] = sumsq;
    __syncthreads();

    for (int stride = ((int)blockDim.x) >> 1; stride > 0; stride >>= 1) {
        if (tid < stride) {
            sh_sum[tid] += sh_sum[tid + stride];
            sh_sumsq[tid] += sh_sumsq[tid + stride];
