    const float* __restrict__ gn_weight,
    const float* __restrict__ gn_bias,
    const float* __restrict__ scale,
    float* __restrict__ out,
    int N, int C, int H, int W, int G,
    int Hp, int Wp,
    float clamp_min, float clamp_max)
